#include <webgpu/wgpu.h>

#include <cstddef>
#include <cstring>
#include <string>

#include "wgpu_internal.h"
#include "wgpu_util.h"
#include "xt_wgpu_shaders.h"  // generated by embed_wgsl.cmake from src/shaders/*.wgsl

/// The pipeline cache (T-438, Docs/design/10-backends.md §10.10.2 "管線快取"): one WGSL module per
/// fragment program (prelude.wgsl + the program's file), three bind group layouts shared by every
/// pipeline, and render pipelines created on first use per `PipelineKey`. The stencil states below
/// are gl_device.cpp's `applyStencil` table, op for op.

namespace xt::wgpu::detail {

namespace {

/// The WGSL file of each ShaderId (prelude.wgsl is prepended).
const char* const kShaderFiles[kShaderCount] = {
    shaders::k_solid,
    shaders::k_gradient,
    shaders::k_texture,
    shaders::k_texture_straight,
    shaders::k_glyph,
    shaders::k_composite,
    shaders::k_particle_texture,
    shaders::k_particle_solid,
    shaders::k_fx_gauss_scalar,
    shaders::k_fx_gauss_color,
    shaders::k_fx_dilate,
    shaders::k_fx_alpha_extract,
    shaders::k_fx_sdf,
    shaders::k_fx_color_matrix,
    shaders::k_fx_gradient_mask,
    shaders::k_fx_shine,
    shaders::k_fx_shadow_glow,
    shaders::k_fx_outline,
    shaders::k_fx_backdrop,
    shaders::k_fx_mask_apply,
    shaders::k_fx_downsample,
    shaders::k_fx_kawase,
    shaders::k_fx_level_mix,
};

/// T-456: the shader of the init probe -- a full-screen triangle and a constant colour, no bindings.
constexpr const char* kProbeWgsl = R"(
@vertex fn vs_probe(@builtin(vertex_index) i: u32) -> @builtin(position) vec4<f32> {
    var p = array<vec2<f32>, 3>(vec2<f32>(-1.0, -1.0), vec2<f32>(3.0, -1.0), vec2<f32>(-1.0, 3.0));
    return vec4<f32>(p[i], 0.0, 1.0);
}
@fragment fn fs_probe() -> @location(0) vec4<f32> {
    return vec4<f32>(1.0, 1.0, 1.0, 1.0);
}
)";

const char* g_probeOverride = nullptr;  ///< setProbeShaderOverride (tests only)

struct ScopeResult {
    bool done = false;
    WGPUErrorType type = WGPUErrorType_NoError;
    std::string message;
};

WGPUShaderModule wgslModule(WGPUDevice device, const std::string& code, const char* name) {
    WGPUShaderSourceWGSL src = WGPU_SHADER_SOURCE_WGSL_INIT;
    src.code = WGPUStringView{code.data(), code.size()};
    WGPUShaderModuleDescriptor d = WGPU_SHADER_MODULE_DESCRIPTOR_INIT;
    d.nextInChain = &src.chain;
    d.label = label(name);
    return wgpuDeviceCreateShaderModule(device, &d);
}

WGPUBindGroupLayoutEntry uniformEntry(uint32_t binding, WGPUShaderStage visibility, uint64_t minSize) {
    WGPUBindGroupLayoutEntry e = WGPU_BIND_GROUP_LAYOUT_ENTRY_INIT;
    e.binding = binding;
    e.visibility = visibility;
    e.buffer.type = WGPUBufferBindingType_Uniform;
    e.buffer.hasDynamicOffset = 1;
    e.buffer.minBindingSize = minSize;
    return e;
}

WGPUBindGroupLayoutEntry textureEntry(uint32_t binding, WGPUTextureSampleType type) {
    WGPUBindGroupLayoutEntry e = WGPU_BIND_GROUP_LAYOUT_ENTRY_INIT;
    e.binding = binding;
    e.visibility = WGPUShaderStage_Fragment;
    e.texture.sampleType = type;
    e.texture.viewDimension = WGPUTextureViewDimension_2D;
    e.texture.multisampled = 0;
    return e;
}

WGPUBindGroupLayout makeLayout(WGPUDevice device, const WGPUBindGroupLayoutEntry* entries, size_t count,
                               const char* name) {
    WGPUBindGroupLayoutDescriptor d = WGPU_BIND_GROUP_LAYOUT_DESCRIPTOR_INIT;
    d.label = label(name);
    d.entryCount = count;
    d.entries = entries;
    return wgpuDeviceCreateBindGroupLayout(device, &d);
}

WGPUPipelineLayout makePipelineLayout(WGPUDevice device, const WGPUBindGroupLayout* groups, size_t count) {
    WGPUPipelineLayoutDescriptor d = WGPU_PIPELINE_LAYOUT_DESCRIPTOR_INIT;
    d.bindGroupLayoutCount = count;
    d.bindGroupLayouts = groups;
    return wgpuDeviceCreatePipelineLayout(device, &d);
}

WGPUSampler makeSampler(WGPUDevice device, WGPUFilterMode filter) {
    WGPUSamplerDescriptor d = WGPU_SAMPLER_DESCRIPTOR_INIT;
    d.addressModeU = d.addressModeV = d.addressModeW = WGPUAddressMode_ClampToEdge;
    d.magFilter = d.minFilter = filter;
    d.mipmapFilter = WGPUMipmapFilterMode_Nearest;
    return wgpuDeviceCreateSampler(device, &d);
}

/// gl_device.cpp applyStencil: compare / read mask / write mask / pass op per StencilOp (fail and
/// depth-fail keep). WriteIncrWrap is the only op whose faces differ.
void stencilState(gpu::StencilOp op, WGPUDepthStencilState& ds) {
    WGPUStencilFaceState f = WGPU_STENCIL_FACE_STATE_INIT;
    f.compare = WGPUCompareFunction_Always;
    f.failOp = f.depthFailOp = f.passOp = WGPUStencilOperation_Keep;
    WGPUStencilFaceState b = f;
    uint32_t read = 0xFF, write = 0x00;
    switch (op) {
        case gpu::StencilOp::WriteIncrWrap:
            f.compare = b.compare = WGPUCompareFunction_Equal;
            f.passOp = WGPUStencilOperation_IncrementWrap;
            b.passOp = WGPUStencilOperation_DecrementWrap;
            read = 0xF0;
            write = 0x0F;
            break;
        case gpu::StencilOp::WriteInvert:
            f.compare = b.compare = WGPUCompareFunction_Equal;
            f.passOp = b.passOp = WGPUStencilOperation_Invert;
            read = 0xF0;
            write = 0x0F;
            break;
        case gpu::StencilOp::TestNotEqualZero:
            f.compare = b.compare = WGPUCompareFunction_NotEqual;  // reference 0
            read = 0x0F;
            break;
        case gpu::StencilOp::TestEqualRef:
            f.compare = b.compare = WGPUCompareFunction_Equal;
            read = 0xF0;
            break;
        case gpu::StencilOp::ClearRect:
            f.passOp = b.passOp = WGPUStencilOperation_Zero;
            write = 0x0F;
            break;
        case gpu::StencilOp::ClipPush:
            // Reference = newDepth << 4, whose low nibble is 0: passes where the winding nibble is
            // non-zero; Replace writes the whole byte (depth up, winding cleared) in one draw.
            f.compare = b.compare = WGPUCompareFunction_NotEqual;
            f.passOp = b.passOp = WGPUStencilOperation_Replace;
            read = 0x0F;
            write = 0xFF;
            break;
        case gpu::StencilOp::ClipPop:
            f.compare = b.compare = WGPUCompareFunction_Equal;
            f.passOp = b.passOp = WGPUStencilOperation_DecrementClamp;  // GL_DECR
            read = 0xF0;
            write = 0xF0;
            break;
        case gpu::StencilOp::None:
        default:
            break;
    }
    ds.stencilFront = f;
    ds.stencilBack = b;
    ds.stencilReadMask = read;
    ds.stencilWriteMask = write;
}

}  // namespace

std::string popErrorScope(WGPUDevice device) {
    ScopeResult scope;
    WGPUPopErrorScopeCallbackInfo cb = WGPU_POP_ERROR_SCOPE_CALLBACK_INFO_INIT;
    cb.mode = WGPUCallbackMode_AllowSpontaneous;
    cb.callback = [](WGPUPopErrorScopeStatus, WGPUErrorType type, WGPUStringView message, void* u1, void*) {
        auto* r = static_cast<ScopeResult*>(u1);
        r->type = type;
        r->message = toString(message);
        r->done = true;
    };
    cb.userdata1 = &scope;
    wgpuDevicePopErrorScope(device, cb);
    for (int i = 0; i < 1000 && !scope.done; ++i) {
        wgpuDevicePoll(device, 0, nullptr);
    }
    if (!scope.done) {
        return "no answer from the error scope";
    }
    if (scope.type == WGPUErrorType_NoError) {
        return std::string();
    }
    return scope.message.empty() ? std::string("unknown WebGPU error") : scope.message;
}

void pushCreationScopes(WGPUDevice device) {
    wgpuDevicePushErrorScope(device, WGPUErrorFilter_Validation);
    wgpuDevicePushErrorScope(device, WGPUErrorFilter_OutOfMemory);
}

std::string popCreationScopes(WGPUDevice device) {
    const std::string oom = popErrorScope(device);
    const std::string validation = popErrorScope(device);
    if (oom.empty() || validation.empty()) {
        return oom.empty() ? validation : oom;
    }
    return oom + "; " + validation;
}

void setProbeShaderOverride(const char* wgsl) { g_probeOverride = wgsl; }

WGPUTextureFormat formatOf(gpu::TextureFormat fmt) {
    switch (fmt) {
        case gpu::TextureFormat::Rgba8:
            return WGPUTextureFormat_RGBA8Unorm;
        case gpu::TextureFormat::R8:
            return WGPUTextureFormat_R8Unorm;
        case gpu::TextureFormat::R32F:
            return WGPUTextureFormat_R32Float;
        case gpu::TextureFormat::Bc1:
            return WGPUTextureFormat_BC1RGBAUnorm;
        case gpu::TextureFormat::Bc3:
            return WGPUTextureFormat_BC3RGBAUnorm;
        case gpu::TextureFormat::Bc7:
            return WGPUTextureFormat_BC7RGBAUnorm;
    }
    return WGPUTextureFormat_Undefined;
}

ShaderId effectShader(gpu::EffectProgram program) {
    using gpu::EffectProgram;
    switch (program) {
        case EffectProgram::GaussScalar:
            return kShFxGaussScalar;
        case EffectProgram::GaussColor:
            return kShFxGaussColor;
        case EffectProgram::Dilate:
            return kShFxDilate;
        case EffectProgram::AlphaExtract:
            return kShFxAlphaExtract;
        case EffectProgram::Sdf:
            return kShFxSdf;
        case EffectProgram::ColorMatrix:
            return kShFxColorMatrix;
        case EffectProgram::GradientMask:
            return kShFxGradientMask;
        case EffectProgram::Shine:
            return kShFxShine;
        case EffectProgram::ShadowGlow:
            return kShFxShadowGlow;
        case EffectProgram::Outline:
            return kShFxOutline;
        case EffectProgram::Backdrop:
            return kShFxBackdrop;
        case EffectProgram::MaskApply:
            return kShFxMaskApply;
        case EffectProgram::Downsample:
            return kShFxDownsample;
        case EffectProgram::Kawase:
            return kShFxKawase;
        case EffectProgram::LevelMix:
            return kShFxLevelMix;
        case EffectProgram::None:
        case EffectProgram::Custom:
        default:
            return kShaderCount;
    }
}

bool Pipelines::init(WGPUDevice device, std::string& err) {
    shutdown();
    m_device = device;
    pushCreationScopes(device);
    const std::string prelude = shaders::k_prelude;
    for (int i = 0; i < kShaderCount; ++i) {
        m_modules[i] = wgslModule(device, prelude + kShaderFiles[i], "xt_wgpu fragment program");
    }
    m_blitModule = wgslModule(device, shaders::k_blit, "xt_wgpu blit");

    const WGPUShaderStage vf = WGPUShaderStage_Vertex | WGPUShaderStage_Fragment;
    const WGPUBindGroupLayoutEntry pass = uniformEntry(0, vf, 48);
    m_bglPass = makeLayout(device, &pass, 1, "xt_wgpu pass constants");
    const WGPUBindGroupLayoutEntry params = uniformEntry(0, vf, kParamBlockBytes);
    m_bglParams = makeLayout(device, &params, 1, "xt_wgpu command parameters");
    WGPUBindGroupLayoutEntry tex[4] = {
        textureEntry(0, WGPUTextureSampleType_Float), textureEntry(1, WGPUTextureSampleType_Float),
        textureEntry(2, WGPUTextureSampleType_Float), WGPU_BIND_GROUP_LAYOUT_ENTRY_INIT};
    tex[3].binding = 3;
    tex[3].visibility = WGPUShaderStage_Fragment;
    tex[3].sampler.type = WGPUSamplerBindingType_Filtering;
    m_bglTextures = makeLayout(device, tex, 4, "xt_wgpu textures");
    tex[1] = textureEntry(1, WGPUTextureSampleType_UnfilterableFloat);
    m_bglTexturesOutline = makeLayout(device, tex, 4, "xt_wgpu textures (R32Float aux)");
    const WGPUBindGroupLayoutEntry blit[2] = {uniformEntry(0, WGPUShaderStage_Fragment, 16),
                                              textureEntry(1, WGPUTextureSampleType_UnfilterableFloat)};
    m_bglBlit = makeLayout(device, blit, 2, "xt_wgpu blit");

    const WGPUBindGroupLayout groups[3] = {m_bglPass, m_bglParams, m_bglTextures};
    m_layout = makePipelineLayout(device, groups, 3);
    const WGPUBindGroupLayout groupsOutline[3] = {m_bglPass, m_bglParams, m_bglTexturesOutline};
    m_layoutOutline = makePipelineLayout(device, groupsOutline, 3);
    m_layoutBlit = makePipelineLayout(device, &m_bglBlit, 1);
    m_linear = makeSampler(device, WGPUFilterMode_Linear);
    m_point = makeSampler(device, WGPUFilterMode_Nearest);

    const std::string scopeError = popCreationScopes(device);
    if (!scopeError.empty()) {
        err = "xt_wgpu shaders: " + scopeError;
        shutdown();
        return false;
    }
    return true;
}

void Pipelines::shutdown() {
    for (auto& kv : m_pipelines) {
        if (kv.second != nullptr) {
            wgpuRenderPipelineRelease(kv.second);
        }
    }
    m_pipelines.clear();
    for (Custom& c : m_custom) {
        if (c.module != nullptr) {
            wgpuShaderModuleRelease(c.module);
        }
    }
    m_custom.clear();
    for (WGPUShaderModule& m : m_modules) {
        if (m != nullptr) {
            wgpuShaderModuleRelease(m);
            m = nullptr;
        }
    }
    if (m_blitModule != nullptr) wgpuShaderModuleRelease(m_blitModule);
    m_blitModule = nullptr;
    if (m_customVertex != nullptr) wgpuShaderModuleRelease(m_customVertex);
    m_customVertex = nullptr;
    for (WGPUPipelineLayout* l : {&m_layout, &m_layoutOutline, &m_layoutBlit}) {
        if (*l != nullptr) wgpuPipelineLayoutRelease(*l);
        *l = nullptr;
    }
    for (WGPUBindGroupLayout* l :
         {&m_bglPass, &m_bglParams, &m_bglTextures, &m_bglTexturesOutline, &m_bglBlit}) {
        if (*l != nullptr) wgpuBindGroupLayoutRelease(*l);
        *l = nullptr;
    }
    for (WGPUSampler* s : {&m_linear, &m_point}) {
        if (*s != nullptr) wgpuSamplerRelease(*s);
        *s = nullptr;
    }
    m_device = nullptr;
    m_lastError.clear();
}

bool Pipelines::probe(WGPUTextureFormat format, uint32_t samples, std::string& err) {
    pushCreationScopes(m_device);
    WGPUShaderModule module =
        wgslModule(m_device, g_probeOverride != nullptr ? g_probeOverride : kProbeWgsl, "xt_wgpu probe");
    WGPURenderPipeline p = nullptr;
    std::string error = popCreationScopes(m_device);
    if (error.empty() && module != nullptr) {
        WGPURenderPipelineDescriptor d = WGPU_RENDER_PIPELINE_DESCRIPTOR_INIT;
        d.label = label("xt_wgpu probe");
        d.vertex.module = module;
        d.vertex.entryPoint = label("vs_probe");
        d.primitive.topology = WGPUPrimitiveTopology_TriangleList;
        d.multisample.count = samples;
        d.multisample.mask = 0xFFFFFFFFu;
        WGPUColorTargetState target = WGPU_COLOR_TARGET_STATE_INIT;
        target.format = format;
        target.writeMask = WGPUColorWriteMask_All;
        WGPUFragmentState fs = WGPU_FRAGMENT_STATE_INIT;
        fs.module = module;
        fs.entryPoint = label("fs_probe");
        fs.targetCount = 1;
        fs.targets = &target;
        d.fragment = &fs;
        pushCreationScopes(m_device);
        p = wgpuDeviceCreateRenderPipeline(m_device, &d);
        error = popCreationScopes(m_device);
    }
    if (p != nullptr) {
        wgpuRenderPipelineRelease(p);
    }
    if (module != nullptr) {
        wgpuShaderModuleRelease(module);
    }
    if (!error.empty() || p == nullptr) {
        err = "the WebGPU backend cannot build a minimal render pipeline (shader compiler unavailable?): " +
              (error.empty() ? std::string("creation returned null") : error);
        return false;
    }
    return true;
}

WGPURenderPipeline Pipelines::checked(WGPURenderPipeline p, const char* what, const PipelineKey& key) {
    std::string error = popCreationScopes(m_device);
    if (error.empty() && p != nullptr) {
        return p;
    }
    if (p != nullptr) {
        wgpuRenderPipelineRelease(p);  // invalid: drawing with it panics wgpu-native at submit
    }
    if (error.empty()) {
        error = "creation returned null";
    }
    if (!m_lastError.empty()) {
        m_lastError += "; ";
    }
    m_lastError += std::string(what) + " (shader " + std::to_string(key.shader) + ", format " +
                   std::to_string(static_cast<uint32_t>(key.format)) + ", " + std::to_string(key.samples) +
                   "x, blend " + std::to_string(static_cast<int>(key.blend)) + ", stencil op " +
                   std::to_string(static_cast<int>(key.stencil)) +
                   ") is unavailable, its draws are skipped: " + error;
    return nullptr;
}

WGPURenderPipeline Pipelines::get(const PipelineKey& key) {
    const uint64_t k = key.packed();
    auto it = m_pipelines.find(k);
    if (it != m_pipelines.end()) {
        return it->second;
    }
    WGPUShaderModule fragment = nullptr;
    if (key.shader < kShaderCount) {
        fragment = m_modules[key.shader];
    } else {
        const size_t idx = key.shader - kShaderCount;
        fragment = idx < m_custom.size() ? m_custom[idx].module : nullptr;
    }
    WGPURenderPipeline p = nullptr;
    if (fragment != nullptr) {
        pushCreationScopes(m_device);
        p = checked(create(key, fragment), "render pipeline", key);
    }
    m_pipelines.emplace(k, p);  // a failure stays cached: never retried, reported once
    return p;
}

WGPURenderPipeline Pipelines::create(const PipelineKey& key, WGPUShaderModule fragment) {
    const bool particles = key.kind == gpu::DrawKind::Particles;
    const bool quad =
        key.shader == kShComposite || (key.shader >= kShFxGaussScalar && key.shader < kShaderCount);
    const bool custom = key.shader >= kShaderCount;

    WGPUVertexAttribute tri[3] = {};
    tri[0].format = WGPUVertexFormat_Float32x3;
    tri[0].offset = offsetof(gpu::Vertex, x);
    tri[0].shaderLocation = 0;
    tri[1].format = WGPUVertexFormat_Float32x2;
    tri[1].offset = offsetof(gpu::Vertex, u);
    tri[1].shaderLocation = 1;
    tri[2].format = WGPUVertexFormat_Unorm8x4;
    tri[2].offset = offsetof(gpu::Vertex, rgba);
    tri[2].shaderLocation = 2;
    WGPUVertexAttribute inst[4] = {};
    inst[0].format = WGPUVertexFormat_Float32x4;
    inst[0].offset = offsetof(gpu::ParticleInstance, x);
    inst[0].shaderLocation = 0;
    inst[1].format = WGPUVertexFormat_Float32;
    inst[1].offset = offsetof(gpu::ParticleInstance, rot);
    inst[1].shaderLocation = 1;
    inst[2].format = WGPUVertexFormat_Unorm8x4;
    inst[2].offset = offsetof(gpu::ParticleInstance, rgba);
    inst[2].shaderLocation = 2;
    inst[3].format = WGPUVertexFormat_Float32x4;
    inst[3].offset = offsetof(gpu::ParticleInstance, u0);
    inst[3].shaderLocation = 3;
    WGPUVertexBufferLayout vb = WGPU_VERTEX_BUFFER_LAYOUT_INIT;
    if (particles) {
        vb.stepMode = WGPUVertexStepMode_Instance;
        vb.arrayStride = sizeof(gpu::ParticleInstance);
        vb.attributeCount = 4;
        vb.attributes = inst;
    } else {
        vb.stepMode = WGPUVertexStepMode_Vertex;
        vb.arrayStride = sizeof(gpu::Vertex);
        vb.attributeCount = 3;
        vb.attributes = tri;
    }

    WGPURenderPipelineDescriptor d = WGPU_RENDER_PIPELINE_DESCRIPTOR_INIT;
    d.label = label("xt_wgpu pipeline");
    d.layout = key.shader == kShFxOutline ? m_layoutOutline : m_layout;
    // A custom program's GLSL fragment pairs with the GLSL vertex stage of wgpu_custom.cpp.
    d.vertex.module = custom ? m_customVertex : fragment;
    d.vertex.entryPoint =
        label(custom ? "main" : (particles ? "vs_particle" : (quad ? "vs_quad" : "vs_main")));
    d.vertex.bufferCount = 1;
    d.vertex.buffers = &vb;
    d.primitive.topology = WGPUPrimitiveTopology_TriangleList;
    d.primitive.frontFace = WGPUFrontFace_CCW;
    d.primitive.cullMode = WGPUCullMode_None;
    WGPUDepthStencilState ds = WGPU_DEPTH_STENCIL_STATE_INIT;
    if (key.hasStencil) {
        ds.format = WGPUTextureFormat_Stencil8;
        ds.depthWriteEnabled = WGPUOptionalBool_False;
        ds.depthCompare = WGPUCompareFunction_Always;
        stencilState(key.stencil, ds);
        d.depthStencil = &ds;
    }
    d.multisample.count = key.samples;
    d.multisample.mask = 0xFFFFFFFFu;

    WGPUBlendState blend = WGPU_BLEND_STATE_INIT;
    blend.color.operation = blend.alpha.operation = WGPUBlendOperation_Add;
    blend.color.srcFactor = blend.alpha.srcFactor = WGPUBlendFactor_One;
    blend.color.dstFactor = blend.alpha.dstFactor =
        key.blend == gpu::Blend::Additive ? WGPUBlendFactor_One : WGPUBlendFactor_OneMinusSrcAlpha;
    WGPUColorTargetState target = WGPU_COLOR_TARGET_STATE_INIT;
    target.format = key.format;
    target.blend = key.blend == gpu::Blend::Replace ? nullptr : &blend;
    target.writeMask = key.colorWrite ? WGPUColorWriteMask_All : WGPUColorWriteMask_None;
    WGPUFragmentState fs = WGPU_FRAGMENT_STATE_INIT;
    fs.module = fragment;
    fs.entryPoint = label(custom ? "main" : "fs_main");
    fs.targetCount = 1;
    fs.targets = &target;
    d.fragment = &fs;
    return wgpuDeviceCreateRenderPipeline(m_device, &d);
}

WGPURenderPipeline Pipelines::blit(WGPUTextureFormat format, uint32_t samples, bool hasStencil) {
    // Keyed apart from the program pipelines by a shader id no program uses.
    PipelineKey key;
    key.shader = 0xFFFF;
    key.blend = gpu::Blend::Replace;
    key.format = format;
    key.samples = static_cast<uint8_t>(samples);
    key.hasStencil = hasStencil;
    const uint64_t k = key.packed();
    auto it = m_pipelines.find(k);
    if (it != m_pipelines.end()) {
        return it->second;
    }
    WGPURenderPipelineDescriptor d = WGPU_RENDER_PIPELINE_DESCRIPTOR_INIT;
    d.label = label("xt_wgpu blit");
    d.layout = m_layoutBlit;
    d.vertex.module = m_blitModule;
    d.vertex.entryPoint = label("vs_blit");
    d.primitive.topology = WGPUPrimitiveTopology_TriangleList;
    d.primitive.cullMode = WGPUCullMode_None;
    WGPUDepthStencilState ds = WGPU_DEPTH_STENCIL_STATE_INIT;
    if (hasStencil) {
        ds.format = WGPUTextureFormat_Stencil8;
        ds.depthWriteEnabled = WGPUOptionalBool_False;
        ds.depthCompare = WGPUCompareFunction_Always;
        stencilState(gpu::StencilOp::None, ds);
        d.depthStencil = &ds;
    }
    d.multisample.count = samples;
    d.multisample.mask = 0xFFFFFFFFu;
    WGPUColorTargetState target = WGPU_COLOR_TARGET_STATE_INIT;
    target.format = format;
    target.writeMask = WGPUColorWriteMask_All;
    WGPUFragmentState fs = WGPU_FRAGMENT_STATE_INIT;
    fs.module = m_blitModule;
    fs.entryPoint = label("fs_blit");
    fs.targetCount = 1;
    fs.targets = &target;
    d.fragment = &fs;
    pushCreationScopes(m_device);
    WGPURenderPipeline p = checked(wgpuDeviceCreateRenderPipeline(m_device, &d), "blit pipeline", key);
    m_pipelines.emplace(k, p);
    return p;
}

}  // namespace xt::wgpu::detail
